WS.weapon.runtime_source:
(id = P.gweapon) => {
    const l = P.skills[id] || 0;
    if (id === 'axe') return { id, dur: 1.05, reach: 1.15, mult: 1.2 + 0.12 * l, arc: 0.9 + 0.02 * l };
    if (id === 'flail') return { id, dur: 1.35, reach: 1.7, mult: 1.4 + 0.18 * l, aoe: 1.0 + 0.03 * l, stun: 0.5 + 0.02 * l };
    return { id: 'sword', dur: 0.75 / (1 + 0.03 * l), reach: 1.05, mult: 1 + 0.15 * l, twice: 0.2 + 0.01 * l };
  }

MS.auraR.runtime_source:
() => {
      const lvl = (P.skills && P.skills.mcloud) || 0;
      const base = 0.35 + 0.15 * Math.max(0, lvl - 1);        // 0.35 at 0, 0.5 at 1, 1.85 at 11, 3.35 at 21
      const fillBonus = 0.9 * MS.frac() * (0.4 + 0.05 * lvl);  // frac matters more with rank
      const thick = (typeof aM === 'function' && aM('zm_thick')) ? 1.2 : 1;
      return (base + fillBonus) * thick;
    }
